package com.testforge.testforge_backend.testsuite.controller;
import com.testforge.testforge_backend.testsuite.dto.*; import com.testforge.testforge_backend.testsuite.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") public class TestSuiteController{private final TestSuiteService service;private final SuiteRunExecutionService runs;private final TestSuiteExportService exports;public TestSuiteController(TestSuiteService s,SuiteRunExecutionService r,TestSuiteExportService e){service=s;runs=r;exports=e;}
 @GetMapping("/projects/{projectId}/test-suites")public List<TestSuiteResponse> list(@PathVariable String projectId){return service.byProject(projectId);}@GetMapping("/projects/{projectId}/test-suites/candidates")public List<TestSuiteResponse.ScenarioMember> candidates(@PathVariable String projectId){return service.candidates(projectId);}@PostMapping("/projects/{projectId}/test-suites")public ResponseEntity<TestSuiteResponse> create(@PathVariable String projectId,@Valid @RequestBody TestSuiteRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(projectId,r));}@PutMapping("/test-suites/{id}")public TestSuiteResponse update(@PathVariable Long id,@Valid @RequestBody TestSuiteRequest r){return service.update(id,r);}@DeleteMapping("/test-suites/{id}")public ResponseEntity<Void> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();}
 @PostMapping("/projects/{projectId}/test-suites/{id}/runs")public ResponseEntity<SuiteRunResponse> run(@PathVariable String projectId,@PathVariable Long id){return ResponseEntity.status(HttpStatus.ACCEPTED).body(runs.execute(projectId,id));}@GetMapping("/test-suite-runs/{id}")public SuiteRunResponse getRun(@PathVariable Long id){return runs.get(id);}@GetMapping("/test-suites/{id}/runs/latest")public ResponseEntity<SuiteRunResponse> latest(@PathVariable Long id){return ResponseEntity.ofNullable(runs.latest(id));}
 @GetMapping("/projects/{projectId}/test-suites/{id}/export")public ResponseEntity<byte[]> export(@PathVariable String projectId,@PathVariable Long id){TestSuiteExportService.ExportedSuite exported=exports.export(projectId,id);return ResponseEntity.ok().contentType(MediaType.parseMediaType("application/zip")).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(exported.fileName()).build().toString()).body(exported.content());}
}
